// @ts-nocheck
import {
	Component,
	Element,
	Event,
	EventEmitter,
	Host,
	Listen,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import merge from "deepmerge";
import { combineMergeArray } from "../../utils/combineMergeArray";
import { debounce } from "../../utils/function-helper";
import { loadMuuri } from "../../utils/muuri";
import constants from "./constants";
import utils from "./utils";

const { scrSizes, scrWidthBreakPoints, scrHeightBreakPoints } = constants;
const { createCustomElement } = utils;

interface Persistence {
	save(id: string, value: unknown): Promise<void>;
	load(id?: string): Promise<unknown>;
	delete(id: string): Promise<void>;
}
@Component({
	tag: "hbr-grid",
	styleUrl: "hbr-grid.scss",
	shadow: false,
})
export class HbrGrid {
	grid;
	private gridInitId = 0;

	@Element() host: HTMLHbrGridElement;

	@Event({ eventName: "hbr-grid-state-updated" })
	gridStateUpdated: EventEmitter<string>;

	/**
	 * Config which contains Muuri props for customization
	 **/
	@Prop() muuriConfig = {};

	/**
	 * Whether it's allowed to delete grid items or not
	 */
	@Prop() removeItemsAllowed = false;

	/**
	 * grid items filtering function
	 */
	@Prop() filterFunction;

	/**
	 * grid items sorting function
	 */
	@Prop() sortFunction;

	/**
	 * selectable - property to enable grid items selection
	 */
	@Prop() selectable = false;

	/**
	 * multiSelect - ability to select multiple grid items
	 */
	@Prop() multiSelect = true;

	/**
	 * Property needed to set filter state for dashlets
	 */
	@Prop() state;

	/**
	 * Type of grid - custom or dashboard.
	 */
	@Prop() type: "custom" | "dashboard" | "cards" = "custom";

	/**
   * An Object that contains functions to update/save Persistence
   * 
   * @State() gridItemsConfigsObj: {
        [uuid: string]: {
          config?: {},
          deleted?: boolean
        }
      } = {};
    
      // developer is getting the following format to save
      persistence.save('grid-persistence-save', {
        order: this.itemsOrderArray,
        gridItems: ~~gridItemsConfigsObj~~
      })
  
      // developer needs to return the following format
      persistence.load() => {
        return {
          order: this.itemsOrderArray,
          gridItems: ~~gridItemsConfigsObj~~
        }
      }
   */
	@Prop() persistence: Persistence | null = null;

	/**
	 * Selected grid items if selectable === true
	 */
	@State() selectedItems: string[] = [];

	/**
	 * Grid items which cannot be selected
	 */
	@State() notSelectabeItems: string[] = [];

	/**
	 * Grid items object
	 */
	@State() gridItemsConfigsObj: {
		[uuid: string]: {
			config?;
			deleted?: boolean;
		};
	} = {};

	/**
	 * Ordered grid items array
	 */
	@State() itemsOrderArray: string[] = [];

	/**
	 * Shows whether grid dependencies (persistence) for initial render is resolved
	 */
	@State() loading = true;

	/**
	 * Property needed to detect whether we move or click on grid item to select it.
	 * Without detection Muuri considers a click as drag&drop causing uncorrect work.
	 */
	@State() isMoving = false;

	@State() dashletsToAdd: number[];

	@Watch("state")
	stateWatcher(state) {
		this.gridStateUpdated.emit(state);
	}

	@Watch("filterFunction")
	filterfunctionWatcher(filterFunc) {
		this.grid.filter((item) => {
			return filterFunc(
				item
					.getElement()
					.firstElementChild.firstElementChild.getAttribute("value"),
			);
		});
	}

	@Watch("sortFunction")
	sortfunctionWatcher(sortFunc) {
		this.grid.sort((a, b) => {
			const getValue = (item) =>
				parseInt(
					item
						.getElement()
						.firstElementChild.firstElementChild.getAttribute("value"),
				);
			return sortFunc(getValue(a), getValue(b));
		});
		this.savePersistence();
	}

	@Watch("isMoving")
	handleDragUpdates(newValue: boolean) {
		this.updateGridItemProps("isMoving", newValue);
	}

	@Watch("selectedItems")
	syncSelection(newValue: string[]) {
		const items = [
			...this.host.querySelectorAll("hbr-grid-item"),
		] as HTMLHbrGridItemElement[];
		items.forEach((item) => {
			if (newValue && newValue.indexOf(item.uuid) !== -1) {
				item.selected = true;
			} else {
				item.selected = false;
			}
		});
	}

	@Watch("muuriConfig")
	async muuriConfigWatcher() {
		if (this.grid) {
			this.grid?.destroy();
			this.grid = undefined;
			await this.initializeMuuri(true);
			this.grid?.layout(true);
		}
	}

	updateGridItemProps(prop: string, value) {
		const items = [
			...this.host.querySelectorAll("hbr-grid-item"),
		] as HTMLHbrGridItemElement[];
		items.forEach((item) => {
			item[prop] = value;
		});
	}

	componentWillLoad() {
		this.getScreenSize();

		if (this.selectable) {
			this.detectNotSelectableItems();
		}
	}

	async componentDidLoad() {
		await this.initializeMuuri();
		if (this.getPreviousGridItems) {
			await this.getPreviousGridItems();
		} else {
			this.loading = false;
		}
		window.addEventListener(
			"resize",
			debounce(() => {
				this.getScreenSize();
			}, 100),
		);
		this.grid?.layout(true);
	}

	async initializeMuuri(layoutOnInit = false) {
		const initId = ++this.gridInitId;
		const { default: Muuri } = await loadMuuri();

		if (initId !== this.gridInitId || !this.host.isConnected) {
			return;
		}

		this.grid = new Muuri(
			this.host,
			merge.all(
				[
					{ layoutOnInit: layoutOnInit }, // default muuri config
					this.muuriConfig, // dev overrides
					constants,
				],
				{ arrayMerge: combineMergeArray },
			),
		);

		this.attachMuuriEvents();
	}

	attachMuuriEvents() {
		if (!this.grid) {
			return;
		}

		// @ts-ignore
		if (this.muuriConfig?.dragEnabled) {
			this.grid.on("dragEnd", () => {
				if (this.isMoving) {
					this.isMoving = false;

					if (this.savePersistence) {
						const gridItems = this.grid?.getItems();
						this.itemsOrderArray = gridItems.map((item) => item._element.uuid);
						this.savePersistence();
					}
				}
			});
			this.grid.on("dragMove", () => {
				if (!this.isMoving) {
					this.isMoving = true;
				}
			});
		}
		this.grid.on("layoutEnd", () => {
			if (this.loading) this.loading = false;
		});
	}

	// Method for react type of frameworks, where props are hidden
	private getGridItem(uuid) {
		return [...this.host.querySelectorAll("hbr-grid-item")].filter(
			(item) => item.uuid === uuid,
		);
	}

	@Listen("hbr-add-grid-item")
	addItemHandler(event: CustomEvent) {
		const uuid = event.detail;
		if (!this.loading) {
			if (this.itemsOrderArray.indexOf(uuid) === -1) {
				// @ts-ignore
				this.gridItemsConfigsObj[uuid] = { config: event.target.config };
				this.itemsOrderArray = [...this.itemsOrderArray, uuid];
				const addedGridItem = this.getGridItem(uuid)[0];
				this.grid?.add([addedGridItem]);
				this.savePersistence();
			} else {
				const addedGridItem = this.getGridItem(uuid)[1];
				if (addedGridItem) {
					addedGridItem.remove();
					alert(`grid item wuth uuid "${uuid}" already exists"`);
				}
			}
		}
		if (this.dashletsToAdd) {
			this.dashletsToAdd.splice(this.dashletsToAdd.indexOf(uuid), 1);
			if (!this.dashletsToAdd.length) {
				this.loading = false;
			}
		}
	}

	@Listen("hbr-remove-grid-item")
	removeGridItemHandler(event: CustomEvent) {
		const uuid = event.detail;
		const index = this.itemsOrderArray.indexOf(uuid);
		if (index !== -1) {
			this.grid.remove(this.grid.getItems(index), { removeElements: true });
			this.itemsOrderArray.splice(this.itemsOrderArray.indexOf(uuid), 1);
			this.gridItemsConfigsObj[uuid] = { deleted: true };
			this.savePersistence();
		} else {
			console.error("Item with such id doesn't exist");
		}
	}

	@Listen("hbr-select-grid-item")
	selectGridItemHandler(event: CustomEvent) {
		const uuid = event.detail;
		if (this.selectable && this.notSelectabeItems.indexOf(uuid) === -1) {
			if (this.selectedItems && Array.isArray(this.selectedItems)) {
				if (this.selectedItems.indexOf(uuid) !== -1) {
					this.selectedItems = this.selectedItems.filter(
						(item) => item !== uuid,
					);
				} else {
					if (this.multiSelect) {
						this.selectedItems = [...this.selectedItems, uuid];
					} else {
						this.selectedItems = [uuid];
					}
				}
			} else {
				this.selectedItems = [uuid];
			}
		}
	}

	private savePersistence() {
		if (this.persistence?.save && typeof this.persistence.save === "function") {
			this.persistence.save("grid-persistence-save", {
				order: this.itemsOrderArray,
				gridItems: this.gridItemsConfigsObj,
			});
		}
	}

	private detectNotSelectableItems() {
		const originalItems = [...this.host.querySelectorAll("hbr-grid-item")];
		const notSelectableItemsList = [];
		originalItems.forEach((item) => {
			if (item.notSelectable) {
				notSelectableItemsList.push(item.uuid);
			}
		});
		this.notSelectabeItems = notSelectableItemsList;
	}

	private getScreenSize = () => {
		let screenWidthSize: string;
		let screenHeightSize: string;
		const screenWidth = window.innerWidth;
		if (screenWidth >= scrWidthBreakPoints[scrSizes.lg]) {
			screenWidthSize = scrSizes.lg;
		} else if (
			screenWidth >= scrWidthBreakPoints[scrSizes.md] &&
			screenWidth < scrWidthBreakPoints[scrSizes.lg]
		) {
			screenWidthSize = scrSizes.md;
		} else {
			screenWidthSize = scrSizes.sm;
		}
		const screenHeight = window.innerHeight;
		if (screenHeight >= scrHeightBreakPoints[scrSizes.lg]) {
			screenHeightSize = scrSizes.lg;
		} else if (
			screenHeight >= scrHeightBreakPoints[scrSizes.md] &&
			screenHeight < scrHeightBreakPoints[scrSizes.lg]
		) {
			screenHeightSize = scrSizes.md;
		} else {
			screenHeightSize = scrSizes.sm;
		}

		this.updateGridItemProps("screenSize", {
			width: screenWidthSize,
			height: screenHeightSize,
		});
	};

	@Method() getSelected() {
		return Promise.resolve(this.selectedItems);
	}

	private getPreviousGridItems = async () => {
		if (this.persistence?.load && typeof this.persistence.load === "function") {
			const pref = await this.persistence.load();
			if (!pref) {
				const gridItems = this.grid?.getItems();
				this.itemsOrderArray = gridItems.map((item) => item._element.uuid);
				this.loading = false;
			} else {
				const { gridItems } = pref || {};
				this.itemsOrderArray = pref.order;
				this.gridItemsConfigsObj = pref.gridItems;

				const deletedItems = [];
				const addedItems = [];
				if (gridItems) {
					const DOMGridItems = this.grid?.getItems();
					Object.keys(gridItems).forEach((uuid, key) => {
						const correntItem = gridItems[uuid];
						const configToStr = JSON.stringify(correntItem.config);
						// get deleted and added items
						if (correntItem.deleted && !correntItem.config) {
							deletedItems.push(DOMGridItems[key]);
						}
						if (
							correntItem.config &&
							configToStr !== "{}" &&
							!correntItem.deleted
						) {
							addedItems.push(uuid);
						}
					});
					if (deletedItems.length) {
						this.grid.remove(deletedItems, { removeElements: true });
					}
					if (addedItems.length) {
						this.dashletsToAdd = addedItems;
						addedItems.forEach((item) => {
							const element = createCustomElement(
								"hbr-grid-item",
								gridItems[item].config,
							);
							this.grid?.add([element]);
						});
					} else {
						this.loading = false;
					}
				}
				this.grid.sort((a, b) => {
					return (
						this.itemsOrderArray.indexOf(a.getElement().uuid) -
						this.itemsOrderArray.indexOf(b.getElement().uuid)
					);
				});
			}
		}
	};

	render() {
		return this.loading ? null : <Host style={{ opacity: "1" }} />;
	}
}
